const CACHE='ngo-report-desk-shell-v12';
const ASSETS=['./','./index.html','./style.css','./app.js','./intake-ui.js','./records.js','./report-contract.js','./donations.js','./photos.js','./sharing.js','./field-notes.js','./report-layout.js','./manifest.webmanifest','./icons/icon-192.png','./icons/icon-512.png','./icons/icon-180.png'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(ASSETS)).then(()=>self.skipWaiting()));});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('ngo-report-desk-shell-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin)return;const allowed=ASSETS.some(p=>new URL(p,self.registration.scope).pathname===url.pathname);if(event.request.mode==='navigate'){event.respondWith(fetch(event.request).catch(()=>caches.match(new URL('./index.html',self.registration.scope).href)));return;}if(allowed)event.respondWith(fetch(event.request).then(response=>{if(!response.ok)throw Error('Asset unavailable');const copy=response.clone();event.waitUntil(caches.open(CACHE).then(cache=>cache.put(event.request,copy)));return response;}).catch(()=>caches.match(event.request)));});
